        background: ed ? s.chips[3].fg : pop ? s.ac : s.box1, borderRadius: ed ? 0 : u(grunge || pop ? 26.25 : 55),
        boxShadow: `${u(1.25)} ${u(1.25)} ${u(10.81)} #00000029`,
